// ---------------------------------------------------------------------------
// Interview setup
// ---------------------------------------------------------------------------

export type InterviewMode =
  | "behavioral"
  | "technical"
  | "system-design"
  | "leetcode"
  | "ai-coding"
  | "custom";

export type Difficulty = "easy" | "medium" | "hard";

/** Models the user can pick for the live interviewer. Cheapest first. */
export type ChatModel = "claude-haiku-5-5" | "claude-sonnet-5-5" | "claude-opus-5-5";

export type VoiceMode = "browser" | "cloud";

export type TurnRole = "interviewer" | "candidate";

/** POST /api/live-token success body: a short-lived Gemini Live token plus the locked session settings. */
export interface LiveTokenResponse {
  token: string;
  model: string;
  config: import("@google/genai").LiveConnectConfig;
}

/** "claude": speech-to-text → Claude → text-to-speech. "gemini-live": Gemini speech-to-speech. */
export type VoiceEngine = "claude" | "gemini-live";

export interface InterviewConfig {
  mode: InterviewMode;
  engine: VoiceEngine;
  /** e.g. "Software Engineer Intern" */
  role: string;
  /** e.g. "Google" — may be empty */
  company: string;
  /** Pasted job description — may be empty */
  jobDescription: string;
  /** Only used when mode === "custom": the user's own scenario description */
  customScenario: string;
  /** Only used when mode === "ai-coding": id from CHALLENGES in lib/challenges.ts */
  challengeId: string;
  difficulty: Difficulty;
  /** Planned length in minutes (15 | 30 | 45 typical) */
  durationMin: number;
  model: ChatModel;
  voice: VoiceMode;
  /** Cloud voice id from VOICE_OPTIONS, or "random" (a new pick each interview). */
  cloudVoice: string;
}

