// ---------------------------------------------------------------------------
// Conversation
// ---------------------------------------------------------------------------

export type CodeLanguage =
  | "python"
  | "javascript"
  | "typescript"
  | "java"
  | "cpp"
  | "go"
  | "pseudocode";

export interface CodeSnapshot {
  language: CodeLanguage;
  content: string;
}

export interface Turn {
  id: string;
  role: TurnRole;
  text: string;
  /** ms since epoch */
  at: number;
  /** Base64 JPEG (NO "data:" prefix) of the shared screen at the time of this candidate turn. */
  screenshot?: string;
  /** Contents of the code panel at the time of this candidate turn. */
  code?: CodeSnapshot;
}

// ---------------------------------------------------------------------------
// HTTP API
// ---------------------------------------------------------------------------

/**
 * POST /api/interview
 * Body: InterviewRequest (JSON).
 * Success: 200, Content-Type text/plain; charset=utf-8, body is the interviewer's
 *          reply streamed as raw text chunks (no SSE framing).
 * Failure: non-2xx with JSON ApiError.
 * When `turns` is empty, the server generates the interviewer's opening line.
 */
export interface InterviewRequest {
  config: InterviewConfig;
  turns: Turn[];
  /** Seconds since the interview started — lets the interviewer pace and wrap up. */
  elapsedSec: number;
  /** The turn ended on a pause, so the interviewer may stay silent (reply WAIT_MARKER). */
  mayWait?: boolean;
  /** Idle check: seconds the candidate has said nothing. Implies mayWait. */
  silentSec?: number;
}

/**
 * POST /api/feedback
 * Body: FeedbackRequest (JSON). Success: 200 JSON FeedbackReport. Failure: ApiError.
 */
export interface FeedbackRequest {
  config: InterviewConfig;
  /** Screenshots may be stripped by the client before sending. */
  turns: Turn[];
  durationSec: number;
  metrics: SpeechMetrics;
}

/**
 * GET  /api/tts → 200 JSON TtsStatus
 * POST /api/tts  Body: { text: string; voice?: string } → 200 audio/mpeg bytes, or ApiError
 *               (503 when cloud voice is not configured). `voice` outside VOICE_OPTIONS
 *               falls back to the server default.
 */
export interface TtsStatus {
  cloudEnabled: boolean;
}

export interface ApiError {
  error: string;
  /**
   * Machine-readable code: "bad_request", "missing_api_key", "invalid_api_key", "permission_denied",
   * "not_found", "rate_limited", "too_large", "upstream_bad_request", "overloaded", "upstream_error",
   * "connection_error", "timeout", "aborted", "internal_error", "refused", "incomplete",
   * "bad_model_output", "cloud_tts_disabled".
   */
  code?: string;
}

// ---------------------------------------------------------------------------
// Feedback & metrics
// ---------------------------------------------------------------------------

export interface SpeechMetrics {
  /** Words spoken by the candidate */
  wordCount: number;
  /** Candidate words per minute, over the interview duration */
  wordsPerMinute: number;
  fillerCount: number;
  /** e.g. { "um": 4, "like": 7 } */
  fillerBreakdown: Record<string, number>;
  /** Number of candidate answers */
  answerCount: number;
  /** Average words per candidate answer */
  avgAnswerWords: number;
}

export interface FeedbackCategory {
  name: string;
  /** 1–10 */
  score: number;
  comment: string;
}

export interface BetterAnswer {
  question: string;
  yourAnswerSummary: string;
  improvedAnswer: string;
}

export interface FeedbackReport {
  /** 1–10 */
  overallScore: number;
  /** "Strong hire" | "Hire" | "Lean hire" | "Lean no hire" | "No hire" */
  verdict: string;
  summary: string;
  categories: FeedbackCategory[];
  strengths: string[];
  improvements: string[];
  betterAnswers: BetterAnswer[];
  nextSteps: string[];
}

/** JSON schema matching FeedbackReport, for structured outputs. */
export const FEEDBACK_JSON_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: [
    "overallScore",
    "verdict",
    "summary",
    "categories",
    "strengths",
    "improvements",
    "betterAnswers",
    "nextSteps",
  ],
  properties: {
    overallScore: { type: "integer" },
    verdict: {
      type: "string",
      enum: ["Strong hire", "Hire", "Lean hire", "Lean no hire", "No hire"],
    },
    summary: { type: "string" },
    categories: {
      type: "array",
      items: {
        type: "object",
        additionalProperties: false,
        required: ["name", "score", "comment"],
        properties: {
          name: { type: "string" },
          score: { type: "integer" },
          comment: { type: "string" },
        },
      },
    },
    strengths: { type: "array", items: { type: "string" } },
    improvements: { type: "array", items: { type: "string" } },
    betterAnswers: {
      type: "array",
      items: {
        type: "object",
        additionalProperties: false,
        required: ["question", "yourAnswerSummary", "improvedAnswer"],
        properties: {
          question: { type: "string" },
          yourAnswerSummary: { type: "string" },
          improvedAnswer: { type: "string" },
        },
      },
    },
    nextSteps: { type: "array", items: { type: "string" } },
  },
} as const;

// ---------------------------------------------------------------------------
// Saved sessions (localStorage)
// ---------------------------------------------------------------------------

export interface SavedSession {
  id: string;
  config: InterviewConfig;
  /** Screenshots are stripped before saving. */
  turns: Turn[];
  startedAt: number;
  durationSec: number;
  metrics: SpeechMetrics;
  feedback?: FeedbackReport;
}

// ---------------------------------------------------------------------------
// MODULE CONTRACTS (signatures each folder must export)
// ---------------------------------------------------------------------------

/** lib/voice/speech.ts — `export function useSpeechRecognition(opts: SpeechOptions): SpeechController` */
export interface SpeechOptions {
  /**
   * Called once when the candidate finishes an answer: either stop() was
   * called, or there was silence for `autoSendAfterMs` (if > 0) after speech.
   * Receives the full accumulated final transcript of that answer (trimmed, non-empty),
   * and whether it ended on a silence pause (true) rather than a deliberate stop().
   */
  onUtterance: (text: string, viaPause: boolean) => void;
  /** Silence (ms) after which the answer is auto-submitted. 0 disables. Default 2500. */
  autoSendAfterMs?: number;
  /** BCP-47 language, default "en-US". */
  lang?: string;
}
export interface SpeechController {
  /** false when the browser has no SpeechRecognition (UI should fall back to typing) */
  supported: boolean;
  listening: boolean;
  /** Live text of the current answer so far (final + interim) */
  transcript: string;
  start: () => void;
  /** Stops listening and submits whatever was captured (via onUtterance). */
  stop: () => void;
  /** Stops listening and discards the current answer. */
  cancel: () => void;
  /** Last error message, if any (e.g. mic permission denied) */
  error: string | null;
}

/**
 * lib/voice/tts.ts — `export function useSpeaker(mode: VoiceMode, voiceId?: string): SpeakerController`
 *   voiceId is a VOICE_OPTIONS id or "random" (picked once per mount, i.e. per interview).
 *   also: `export function unlockAudio(): void` — call synchronously inside a click handler
 *   (required for iOS audio), and `export function cleanForSpeech(text: string): string`.
 */
export interface SpeakerController {
  /** Browser speech or cloud voice available at all */
  supported: boolean;
  /** True while audio is playing or queued */
  speaking: boolean;
  /** Whether the cloud voice is actually in use (cloud requested AND server has it enabled) */
  usingCloud: boolean;
  /** Feed streamed text deltas; complete sentences are spoken as soon as they're available. */
  feed: (delta: string) => void;
  /** Speak whatever is left in the buffer (call when the stream ends). */
  flush: () => void;
  /** Speak a full text immediately (queued after current speech). */
  say: (text: string) => void;
  /** Stop all speech and clear the queue (e.g. candidate interrupts). */
  cancel: () => void;
  muted: boolean;
  setMuted: (muted: boolean) => void;
}

/**
 * lib/capture/frame.ts
 *   export function isScreenShareSupported(): boolean
 *   export async function captureFrame(stream: MediaStream, maxWidth?: number, quality?: number): Promise<string | null>
 *     → base64 JPEG without "data:" prefix, or null if the stream has no live video.
 *   export function framesDiffer(a: string | null, b: string | null): boolean
 *     → cheap "did the screen change?" check, used to skip resending identical screenshots.
 *
 * components/capture/ScreenShare.tsx
 *   export default function ScreenShare(props: ScreenShareProps): JSX.Element
 *
 * components/capture/CodePanel.tsx
 *   export default function CodePanel(props: CodePanelProps): JSX.Element
 */
export interface ScreenShareProps {
  /** Called with the active stream when sharing starts, and null when it stops. */
  onStreamChange: (stream: MediaStream | null) => void;
  /** Compact rendering for small screens / side panels */
  compact?: boolean;
}
export interface CodePanelProps {
  value: string;
  language: CodeLanguage;
  onChange: (value: string) => void;
  onLanguageChange: (language: CodeLanguage) => void;
  /** Optional visible title, defaults to "Code" */
  title?: string;
}
